function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var R=prng(seed*299999+61);var toH=0,toA=0,esc=0;for(var i=0;i<12;i++){var unc=R(),imp=R();if(imp>0.8||unc>0.75)toH++;else if(imp<0.35&&unc<0.4)toA++;else esc++;}return{decisions:12,routed_to_human:toH,routed_to_ai:toA,escalated_review:esc};}
var SEED = 94001;
console.log(JSON.stringify(demoRun(SEED), null, 1));

